package com.greenocean.backend.moderation.service;

import com.greenocean.backend.auth.service.RecentAuthentication;
import com.greenocean.backend.common.exception.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

/** One-use, independently approved attribution of an exact active safety revision. */
@Service @Transactional
public class SocialAttribution {
 private final JdbcTemplate db;private final RecentAuthentication recent;private final com.greenocean.backend.identity.AccessPolicy access;
 public SocialAttribution(JdbcTemplate db,RecentAuthentication recent,com.greenocean.backend.identity.AccessPolicy access){this.db=db;this.recent=recent;this.access=access;}
 private void admin(UUID who,UUID sid){db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",who);access.require(who,"COMMUNITY");recent.require(who,sid,true);if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND u.status='ACTIVE' AND u.email_verified AND u.deleted_at IS NULL AND r.name='ADMIN')",Boolean.class,who)))throw new ForbiddenException("Current administrator evidence authority and strong MFA required");}
 private Map<String,Object> assessment(UUID id){var rows=db.queryForList("SELECT * FROM social_assessments WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new NotFoundException("Safety revision unavailable");var a=rows.getFirst();boolean post=a.get("post_id")!=null;var c=db.queryForList("SELECT author_id,revision,status FROM "+(post?"posts":"comments")+" WHERE id=? FOR UPDATE",a.get(post?"post_id":"comment_id"));if(c.isEmpty()||"DELETED".equals(c.getFirst().get("status"))||!a.get("revision").equals(c.getFirst().get("revision")))throw new ConflictException("Only the current nondeleted safety revision may be reviewed");
  boolean reported=Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM reports WHERE(post_id=? OR comment_id=?) AND status IN('PENDING','IN_REVIEW'))",Boolean.class,a.get("post_id"),a.get("comment_id")));
  if("ALLOW".equals(a.get("outcome"))&&!reported)throw new ForbiddenException("A current safety hold or open source report is required");a.put("subject_id",c.getFirst().get("author_id"));return a;}
 private void independent(UUID who,Map<String,Object> a){if(who.equals(a.get("subject_id")))throw new ForbiddenException("Independent evidence review required");}
 private int version(UUID who,UUID sid){return db.queryForObject("SELECT token_version FROM user_sessions WHERE id=? AND user_id=? AND revoked_at IS NULL FOR SHARE",Integer.class,sid,who);}
 private void audit(UUID who,UUID id,String action,String purpose){db.update("INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,metadata) VALUES(?,?,'SOCIAL_ASSESSMENT',?,jsonb_build_object('purpose',?::text))",who,action,id,purpose);}
 public UUID request(UUID who,UUID sid,UUID assessment,long revision,String purpose){admin(who,sid);if(!Set.of("THREAT_INVESTIGATION","PRIVACY_COMPLAINT","ACCOUNT_SECURITY").contains(purpose))throw new IllegalArgumentException("Choose a fixed necessary safety purpose; do not copy private narrative");var a=assessment(assessment);independent(who,a);if(((Number)a.get("revision")).longValue()!=revision)throw new ConflictException("Review the exact safety revision");db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","social-attribution-budget:"+who);if(db.queryForObject("SELECT count(*) FROM social_attribution_requests WHERE requester_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 hour'",Integer.class,who)>=10)throw new TooManyRequestsException("Pause before more exceptional access requests",3600);UUID id=UUID.randomUUID();db.update("INSERT INTO social_attribution_requests(id,assessment_id,revision,requester_id,request_session,request_version,purpose,expires_at) VALUES(?,?,?,?,?,?,?,CURRENT_TIMESTAMP+INTERVAL '15 minutes')",id,assessment,revision,who,sid,version(who,sid),purpose);audit(who,assessment,"SOCIAL_ATTRIBUTION_REQUESTED",purpose);return id;}
 private Map<String,Object> locked(UUID id){var rows=db.queryForList("SELECT assessment_id,requester_id,approved_by FROM social_attribution_requests WHERE id=?",id);if(rows.isEmpty())throw new NotFoundException("Evidence request unavailable");var before=rows.getFirst();db.queryForList("SELECT id FROM users WHERE id=? OR id=? ORDER BY id FOR SHARE",before.get("requester_id"),before.get("approved_by"));var a=assessment((UUID)before.get("assessment_id"));var r=db.queryForMap("SELECT *,expires_at>CURRENT_TIMESTAMP AS live FROM social_attribution_requests WHERE id=? FOR UPDATE",id);if(!Objects.equals(before.get("approved_by"),r.get("approved_by")))throw new ConflictException("Evidence approval changed; reload before continuing");if(!Boolean.TRUE.equals(r.get("live"))||r.get("revoked_at")!=null||r.get("consumed_at")!=null||!r.get("revision").equals(a.get("revision")))throw new ConflictException("Evidence request expired, changed or was already consumed");r.put("subject_id",a.get("subject_id"));return r;}
 public void approve(UUID who,UUID sid,UUID id,long revision){admin(who,sid);var r=locked(id);independent(who,r);if(who.equals(r.get("requester_id")))throw new ForbiddenException("A second independent administrator must approve");if(((Number)r.get("revision")).longValue()!=revision||r.get("approved_by")!=null)throw new ConflictException("Review this exact unapproved request");UUID requester=(UUID)r.get("requester_id"),session=(UUID)r.get("request_session");admin(requester,session);if(!Objects.equals(r.get("request_version"),version(requester,session)))throw new ConflictException("Requesting session changed");db.update("UPDATE social_attribution_requests SET approved_by=?,approval_session=?,approval_version=? WHERE id=?",who,sid,version(who,sid),id);audit(who,(UUID)r.get("assessment_id"),"SOCIAL_ATTRIBUTION_APPROVED",(String)r.get("purpose"));}
 public Map<String,Object> reveal(UUID who,UUID sid,UUID assessment,UUID request){admin(who,sid);var r=locked(request);if(!who.equals(r.get("requester_id"))||!sid.equals(r.get("request_session"))||!assessment.equals(r.get("assessment_id")))throw new NotFoundException("Own session-bound evidence request required");if(r.get("approved_by")==null)throw new ForbiddenException("Independent approval is required before attribution");independent(who,r);UUID reviewer=(UUID)r.get("approved_by"),reviewSession=(UUID)r.get("approval_session");admin(reviewer,reviewSession);if(!Objects.equals(r.get("request_version"),version(who,sid))||!Objects.equals(r.get("approval_version"),version(reviewer,reviewSession)))throw new ConflictException("A participating session changed");db.update("UPDATE social_attribution_requests SET consumed_at=CURRENT_TIMESTAMP WHERE id=?",request);audit(who,assessment,"SOCIAL_IDENTITY_REVIEW",(String)r.get("purpose"));return Map.of("authorId",r.get("subject_id"));}
 public void revoke(UUID who,UUID sid,UUID id){admin(who,sid);var r=db.queryForList("SELECT assessment_id,purpose FROM social_attribution_requests WHERE id=? AND(requester_id=? OR approved_by=?) FOR UPDATE",id,who,who);if(r.isEmpty())throw new NotFoundException("Own evidence request required");db.update("UPDATE social_attribution_requests SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE id=?",id);audit(who,(UUID)r.getFirst().get("assessment_id"),"SOCIAL_ATTRIBUTION_REVOKED",(String)r.getFirst().get("purpose"));}
 public List<Map<String,Object>> queue(UUID who,UUID sid){admin(who,sid);return db.queryForList("SELECT id,assessment_id,revision,purpose,requester_id=? AS own_request,(requester_id=? OR approved_by=?) AS can_revoke,approved_by IS NOT NULL AS approved,expires_at FROM social_attribution_requests WHERE revoked_at IS NULL AND consumed_at IS NULL AND expires_at>CURRENT_TIMESTAMP ORDER BY created_at,id LIMIT 50",who,who,who);}
}
